      cat(x + 50, y + 28, 0.75, '#a7d7c3') + repeat(extra + 2, i =>
        cat(x + 50 + (i - (extra + 1) / 2) * 21, y + 62, 0.5, gold));
    let body = '';
    if (step === 1) body = family(270, 100, 0) + text(320, 64, 'Одна семья', 26);
    if (step === 2) body = repeat(4, i => family(104 + 108 * i, 102, i === 3 ? 2 : 0)) +
      text(320, 60, '3 + 3 + 3 + 5 = 14', 27, teal);
